using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Aster {
class SpecDifference {public string Field,Before,After,Change;}
static class ReportComparison {
 public static Dictionary<string,string> Parse(string text){var result=new Dictionary<string,string>(StringComparer.Ordinal);foreach(string raw in text.Split('\n')){string line=raw.Trim();int split=line.IndexOf(": ",StringComparison.Ordinal);if(split>0&&line.Substring(0,split).Contains(" · ")){string key=line.Substring(0,split);if(result.ContainsKey(key))throw new Exception("Report contains duplicate specification keys: "+key);result[key]=line.Substring(split+2);}}if(result.Count==0)throw new Exception("No Aster hardware fields were found. Choose an exported Hardware report.");return result;}
 public static List<SpecDifference> Compare(string before,string after){var a=Parse(before);var b=Parse(after);return a.Keys.Union(b.Keys).OrderBy(k=>k).Select(k=>{string old,newValue;bool had=a.TryGetValue(k,out old),has=b.TryGetValue(k,out newValue);return new SpecDifference{Field=k,Before=had?old:"—",After=has?newValue:"—",Change=!had?"Added":!has?"Removed":old==newValue?"Unchanged":"Changed"};}).ToList();}
 public static string Read(string path){if(new FileInfo(path).Length>1048576)throw new Exception("Hardware reports must be smaller than 1 MB.");string data=File.ReadAllText(path);Parse(data);return data;}
}
partial class MainWindow {
 static readonly string[] HomeLabels={"Personal welcome & calendar","Live CPU / RAM / GPU / network cards","Quick action buttons","CPU and memory history charts","Busy processes and hardware overview","GPU sensor readings","Network and disk activity details"};
 bool[] HomeSelection(){return preferences.HomeSections!=null&&preferences.HomeSections.Length==7&&preferences.HomeSections.Any(x=>x)?preferences.HomeSections:new[]{true,true,true,true,true,true,true};}
 void ApplyHomeLayout(TableLayoutPanel layout){int[] heights={150,134,50,220,225,105,95};var selected=HomeSelection();for(int row=0;row<7;row++){layout.RowStyles[row].Height=selected[row]?heights[row]:0;foreach(Control control in layout.Controls)if(layout.GetRow(control)==row)control.Visible=selected[row];}layout.Height=Enumerable.Range(0,7).Where(i=>selected[i]).Sum(i=>heights[i])+12;}
 void BuildHomeLayout(){sub.Text="Choose what belongs on Summary · presets or your own selection";var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(16)};content.Controls.Add(flow);flow.Controls.Add(new Label{Text="Your home, your way.",AutoSize=true,Font=new Font("Segoe UI",24,FontStyle.Bold)});flow.Controls.Add(new Label{Text="Hide sections you do not need. Your data and monitoring history stay intact.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,12,0,18)});var list=new CheckedListBox{Width=680,Height=245,CheckOnClick=true,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",12)};var selection=HomeSelection();for(int i=0;i<7;i++)list.Items.Add(HomeLabels[i],selection[i]);flow.Controls.Add(list);var presets=new FlowLayoutPanel{Width=700,Height=50};flow.Controls.Add(presets);Action<bool[]> set=values=>{for(int i=0;i<7;i++)list.SetItemChecked(i,values[i]);};foreach(string preset in new[]{"Everything","Essentials","Quiet dashboard"}){string name=preset;var button=Button(preset);button.Click+=(s,e)=>set(name=="Everything"?new[]{true,true,true,true,true,true,true}:name=="Essentials"?new[]{true,true,true,true,false,false,false}:new[]{true,true,false,false,false,false,false});presets.Controls.Add(button);}var save=Button("Save layout & open Summary");save.Click+=(s,e)=>{var values=Enumerable.Range(0,7).Select(i=>list.GetItemChecked(i)).ToArray();if(!values.Any(x=>x)){MessageBox.Show(this,"Keep at least one Summary section.");return;}preferences.HomeSections=values;SavePreferences();Navigate("Summary");};flow.Controls.Add(save);}
 void BuildHardwareCompare(){sub.Text="Compare two Aster hardware reports · changes are observations, not fault diagnoses";string before=null,after=null;List<SpecDifference> differences=null;var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,90));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(root);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};root.Controls.Add(actions,0,0);var state=new Label{Dock=DockStyle.Fill,Text="Load two saved Hardware reports, or load an older report and capture current specs."};root.Controls.Add(state,0,1);var table=MakeGrid();foreach(string column in new[]{"Specification","Before","After","Change"})table.Columns.Add(column,column);table.Columns[0].FillWeight=140;root.Controls.Add(table,0,2);var only=new CheckBox{Text="Changes only",Checked=true,AutoSize=true,Margin=new Padding(8,8,8,0)};Action render=()=>{table.Rows.Clear();if(differences!=null)foreach(var d in differences.Where(d=>!only.Checked||d.Change!="Unchanged"))table.Rows.Add(d.Field,d.Before,d.After,d.Change);};Action compare=()=>{if(before==null||after==null)return;differences=ReportComparison.Compare(before,after);state.Text=differences.Count(d=>d.Change!="Unchanged")+" changed / added / removed fields · "+differences.Count+" total. Provider availability can also change.";render();};Action<Action> guard=a=>{try{a();}catch(Exception ex){state.Text=ex.Message;}};foreach(string side in new[]{"before","after"}){string which=side;var load=Button("Load "+side+" report");load.Click+=(s,e)=>guard(()=>{using(var d=new OpenFileDialog{Filter="Hardware report|*.txt"})if(d.ShowDialog(this)==DialogResult.OK){string text=ReportComparison.Read(d.FileName);if(which=="before")before=text;else after=text;state.Text="Loaded "+which+": "+Path.GetFileName(d.FileName);compare();}});actions.Controls.Add(load);}var capture=Button("Capture current as after");capture.Click+=async(s,e)=>{capture.Enabled=false;state.Text="Reading hardware providers…";try{string value=await Task.Run(()=>HardwareReport.Collect());if(table.IsDisposed)return;ReportComparison.Parse(value);after=value;state.Text="Current report captured.";compare();}catch(Exception ex){if(!state.IsDisposed)state.Text=ex.Message;}finally{if(!capture.IsDisposed)capture.Enabled=true;}};actions.Controls.Add(capture);actions.Controls.Add(only);only.CheckedChanged+=(s,e)=>render();var export=Button("Export comparison");export.Click+=(s,e)=>guard(()=>{if(differences==null)throw new Exception("Load both reports first.");SaveCsv("hardware-comparison",new[]{new[]{"Specification","Before","After","Change"}}.Concat(differences.Select(d=>new[]{d.Field,d.Before,d.After,d.Change})));});actions.Controls.Add(export);var ai=Button("Prepare AI explanation");ai.Click+=(s,e)=>{if(differences==null){state.Text="Load both reports first.";return;}string evidence=string.Join("\r\n",differences.Where(d=>d.Change!="Unchanged").Take(35).Select(d=>d.Field+": "+d.Before+" → "+d.After));if(evidence.Length>4800)evidence=evidence.Substring(0,4800)+"\r\n[truncated]";Navigate("Windows advisor");var advisor=content.Controls.OfType<AdvisorPanel>().FirstOrDefault();if(advisor!=null)advisor.PrepareEvidence("Hardware report comparison (up to 35 differing fields). These are not proven faults.\r\n"+(evidence.Length==0?"No differences found.":evidence));};actions.Controls.Add(ai);}
}
}
